import{_ as t,o as a,c as r,al as d}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"ADS-B/FLARM/UTM Receivers: Air Traffic Avoidance","description":"","frontmatter":{},"headers":[],"relativePath":"ko/peripherals/adsb_flarm.md","filePath":"ko/peripherals/adsb_flarm.md"}'),i={name:"ko/peripherals/adsb_flarm.md"};function o(n,e,c,s,l,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="ads-b-flarm-utm-receivers-air-traffic-avoidance" tabindex="-1">ADS-B/FLARM/UTM Receivers: Air Traffic Avoidance <a class="header-anchor" href="#ads-b-flarm-utm-receivers-air-traffic-avoidance" aria-label="Permalink to &quot;ADS-B/FLARM/UTM Receivers: Air Traffic Avoidance&quot;">​</a></h1><p>PX4 can monitor cooperative air traffic reported by <a href="https://en.wikipedia.org/wiki/Automatic_dependent_surveillance_%E2%80%93_broadcast" target="_blank" rel="noreferrer">ADS-B</a>, <a href="https://en.wikipedia.org/wiki/FLARM" target="_blank" rel="noreferrer">FLARM</a>, or <a href="https://www.faa.gov/uas/advanced_operations/traffic_management" target="_blank" rel="noreferrer">UTM</a> integrations. When it detects a potential conflict, PX4 can warn the operator or request an action such as Hold, Return, Land, or Terminate.</p><p>This page explains how to connect a supported receiver and configure traffic avoidance behavior. It is most relevant for operations in shared airspace, particularly beyond visual line of sight (BVLOS), where the vehicle must maintain safe separation from manned aviation without an onboard pilot.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 can only assess <em>cooperative</em> traffic: aircraft that actively broadcast their position via ADS-B, FLARM, UTM, or a compatible integration. If your operation does not involve that kind of traffic data, this page is unlikely to apply.</p><p>For details on conflict-detection logic, alert volumes, notifications, testing, and extension points, see <a href="./../advanced_features/detect_and_avoid">Detect and Avoid</a>.</p></div><h2 id="지원-하드웨어" tabindex="-1">지원 하드웨어 <a class="header-anchor" href="#지원-하드웨어" aria-label="Permalink to &quot;지원 하드웨어&quot;">​</a></h2><p>PX4 traffic avoidance works directly with ADS-B and FLARM products that send MAVLink <a href="https://mavlink.io/en/messages/common.html#ADSB_VEHICLE" target="_blank" rel="noreferrer"><code>ADSB_VEHICLE</code></a>. DAA consumes PX4&#39;s <code>transponder_report</code> topic, so other traffic sources can be supported by an adapter that publishes compatible reports.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 does not currently convert incoming MAVLink <a href="https://mavlink.io/en/messages/common.html#UTM_GLOBAL_POSITION" target="_blank" rel="noreferrer"><code>UTM_GLOBAL_POSITION</code></a> messages into traffic reports. A UTM integration therefore needs a separate <code>transponder_report</code> adapter.</p></div><p>It has been tested with the following devices:</p><ul><li><a href="https://uavionix.com/product/pingrx-pro/" target="_blank" rel="noreferrer">PingRX ADS-B Receiver</a> (uAvionix)</li><li><a href="https://www.flarm.com/en/drones/" target="_blank" rel="noreferrer">FLARM</a></li></ul><h2 id="하드웨어-설정" tabindex="-1">하드웨어 설정 <a class="header-anchor" href="#하드웨어-설정" aria-label="Permalink to &quot;하드웨어 설정&quot;">​</a></h2><p>Any of the devices can be connected to any free/unused serial port on the flight controller. Most commonly they are connected to <code>TELEM2</code> (if this is not being used for some other purpose).</p><h3 id="pingrx-pro" tabindex="-1">PingRX Pro <a class="header-anchor" href="#pingrx-pro" aria-label="Permalink to &quot;PingRX Pro&quot;">​</a></h3><p>The PingRX MAVLink port uses a JST ZHR-4 mating connector with pinout as shown below.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>RX (입력)</td><td>+5V tolerant</td></tr><tr><td>2 (흑)</td><td>TX (출력)</td><td></td></tr><tr><td>3 (흑)</td><td>전원</td><td>+4 to 6V</td></tr><tr><td>4 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><p>The PingRX comes with connector cable that can be attached directly to the <code>TELEM2</code> port (DF13-6P) on an <a href="./../flight_controller/mro_pixhawk">mRo Pixhawk</a>. For other ports or boards, you will need to obtain your own cable.</p><p>The recommended port configuration for this receiver is:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Recommended Value</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_CONFIG">MAV_X_CONFIG</a></td><td><code>TELEM 2</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_MODE">MAV_X_MODE</a></td><td>uAvionix</td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_RADIO_CTL">MAV_X_RADIO_CTL</a></td><td>Disabled</td></tr></tbody></table><h2 id="flarm" tabindex="-1">FLARM <a class="header-anchor" href="#flarm" aria-label="Permalink to &quot;FLARM&quot;">​</a></h2><p>FLARM has an on-board DF-13 6 Pin connector that has an identical pinout to the <a href="./../flight_controller/mro_pixhawk">mRo Pixhawk</a>.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>VCC</td><td>+4V to +36V</td></tr><tr><td>2 (흑)</td><td>TX (출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>RX (입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>-</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>-</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The TX and RX on the flight controller must be connected to the RX and TX on the FLARM, respectively.</p></div><h2 id="px4-설정" tabindex="-1">PX4 설정 <a class="header-anchor" href="#px4-설정" aria-label="Permalink to &quot;PX4 설정&quot;">​</a></h2><h3 id="port-configuration" tabindex="-1">Port Configuration <a class="header-anchor" href="#port-configuration" aria-label="Permalink to &quot;Port Configuration&quot;">​</a></h3><p>The receivers are configured in the same way as any other <a href="./../peripherals/mavlink_peripherals">MAVLink Peripheral</a>. The recommended configuration for most devices (unless they have device-specific configuration like PingRX) is to connect to <code>TELEM 2</code> and <a href="./../advanced_config/parameters">set the parameters</a> as shown:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Recommended Value</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_CONFIG">MAV_X_CONFIG</a></td><td><code>TELEM 2</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_MODE">MAV_X_MODE</a></td><td>Normal</td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_RATE">MAV_X_RATE</a></td><td>0 (default sending rate for port)</td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_FORWARD">MAV_X_FORWARD</a></td><td>Enabled</td></tr></tbody></table><p>Then reboot the vehicle.</p><p>You will now find a new parameter called <a href="./../advanced_config/parameter_reference#SER_TEL2_BAUD">SER_TEL2_BAUD</a>, which must be set to 57600.</p><h3 id="configure-traffic-avoidance" tabindex="-1">Configure Traffic Avoidance <a class="header-anchor" href="#configure-traffic-avoidance" aria-label="Permalink to &quot;Configure Traffic Avoidance&quot;">​</a></h3><p>Traffic avoidance is included when the firmware is built with <code>CONFIG_NAVIGATOR_ADSB</code>. The conflict model is also selected at build time:</p><ul><li><strong>Crosstrack mode</strong> is used when <code>CONFIG_NAVIGATOR_ADSB_F3442</code> is disabled. It raises one conflict level and action when the current vehicle is close to the traffic&#39;s predicted track, vertically close, and within a configured collision-time threshold. This is the avoidance mode historically supported by PX4.</li><li><strong>F3442 mode</strong> is used when <code>CONFIG_NAVIGATOR_ADSB_F3442</code> is enabled. It evaluates four alert tests derived from concepts in <a href="https://store.astm.org/f3442_f3442m-23.html" target="_blank" rel="noreferrer">ASTM F3442/F3442M-23</a> and supports a separate action for each result level.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The F3442 mode processes cooperative traffic only and implements selected alert concepts and thresholds. It does not by itself establish compliance with ASTM F3442/F3442M-23, which applies to the complete DAA system and its compliance evidence. The implementation references the 2023 edition and has not been evaluated against the later <a href="https://store.astm.org/f3442-25.html" target="_blank" rel="noreferrer">ASTM F3442-25</a> edition.</p></div><p>For the detailed behavior of each conflict model, see <a href="./../advanced_features/detect_and_avoid#conflict-standards">Detect and Avoid &gt; Conflict Standards</a> and <a href="./../advanced_features/detect_and_avoid#automated-actions">Detect and Avoid &gt; Automated Actions</a>.</p><h4 id="enable-avoidance" tabindex="-1">Enable Avoidance <a class="header-anchor" href="#enable-avoidance" aria-label="Permalink to &quot;Enable Avoidance&quot;">​</a></h4><p>Use <a href="./../advanced_config/parameter_reference#DAA_EN">DAA_EN</a> to enable or disable DAA at runtime.</p><h4 id="crosstrack" tabindex="-1">Crosstrack <a class="header-anchor" href="#crosstrack" aria-label="Permalink to &quot;Crosstrack&quot;">​</a></h4><p>Use firmware built without <code>CONFIG_NAVIGATOR_ADSB_F3442</code> if you want the single-threshold traffic avoidance behavior.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>설명</th></tr></thead><tbody><tr><td><a id="NAV_TRAFF_AVOID"></a><a href="./../advanced_config/parameter_reference#NAV_TRAFF_AVOID">NAV_TRAFF_AVOID</a></td><td>Action requested when the crosstrack threshold is breached. <code>0</code>: Disabled, <code>1</code>: Warn only, <code>2</code>: Return, <code>3</code>: Land, <code>4</code>: Hold, <code>5</code>: Terminate.</td></tr><tr><td><a id="NAV_TRAFF_A_HOR"></a><a href="./../advanced_config/parameter_reference#NAV_TRAFF_A_HOR">NAV_TRAFF_A_HOR</a></td><td>Maximum absolute crosstrack distance from the projected traffic track.</td></tr><tr><td><a id="NAV_TRAFF_A_VER"></a><a href="./../advanced_config/parameter_reference#NAV_TRAFF_A_VER">NAV_TRAFF_A_VER</a></td><td>Maximum vertical separation from the traffic aircraft.</td></tr><tr><td><a id="NAV_TRAFF_COLL_T"></a><a href="./../advanced_config/parameter_reference#NAV_TRAFF_COLL_T">NAV_TRAFF_COLL_T</a></td><td>Maximum conservative time-to-collision estimate. A conflict is raised only if the horizontal, vertical, and time conditions are all met.</td></tr></tbody></table><h4 id="f3442" tabindex="-1">F3442 <a class="header-anchor" href="#f3442" aria-label="Permalink to &quot;F3442&quot;">​</a></h4><p>Use firmware built with <code>CONFIG_NAVIGATOR_ADSB_F3442</code> for staged alerting based on selected ASTM F3442/F3442M-23 concepts.</p><p>PX4 evaluates four conflict levels and maps each level to an action:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>설명</th></tr></thead><tbody><tr><td><a id="DAA_LVL_LOW_ACT"></a><a href="./../advanced_config/parameter_reference#DAA_LVL_LOW_ACT">DAA_LVL_LOW_ACT</a></td><td>Action for the augmented well clear alert volume.</td></tr><tr><td><a id="DAA_LVL_MED_ACT"></a><a href="./../advanced_config/parameter_reference#DAA_LVL_MED_ACT">DAA_LVL_MED_ACT</a></td><td>Action for the augmented NMAC alert volume.</td></tr><tr><td><a id="DAA_LVL_HIGH_ACT"></a><a href="./../advanced_config/parameter_reference#DAA_LVL_HIGH_ACT">DAA_LVL_HIGH_ACT</a></td><td>Action for Loss of Well Clear (LoWC).</td></tr><tr><td><a id="DAA_LVL_CRIT_ACT"></a><a href="./../advanced_config/parameter_reference#DAA_LVL_CRIT_ACT">DAA_LVL_CRIT_ACT</a></td><td>Action for Near Mid-Air Collision (NMAC).</td></tr></tbody></table><p>F3442 mode evaluates four cylindrical alert tests in priority order. A test is breached when both horizontal and vertical separation are inside its combined ownship (the current vehicle) plus traffic bounds.</p><table tabindex="0"><thead><tr><th>항목</th><th>매개변수</th><th>설명</th></tr></thead><tbody><tr><td><code>CRITICAL</code></td><td><a href="./../advanced_config/parameter_reference#DAA_LVL_CRIT_RAD">DAA_LVL_CRIT_RAD</a>, <a href="./../advanced_config/parameter_reference#DAA_LVL_CRIT_HGT">DAA_LVL_CRIT_HGT</a></td><td>Per-aircraft NMAC base radius and vertical bound.</td></tr><tr><td><code>HIGH</code></td><td><a href="./../advanced_config/parameter_reference#DAA_LVL_HIGH_RAD">DAA_LVL_HIGH_RAD</a>, <a href="./../advanced_config/parameter_reference#DAA_LVL_HIGH_HGT">DAA_LVL_HIGH_HGT</a></td><td>Per-aircraft Well Clear base radius and vertical bound.</td></tr><tr><td><code>MEDIUM</code></td><td><a href="./../advanced_config/parameter_reference#DAA_LVL_MED_TIME">DAA_LVL_MED_TIME</a></td><td>Expands the NMAC base volume using aircraft speed and the configured time margin.</td></tr><tr><td><code>LOW</code></td><td><a href="./../advanced_config/parameter_reference#DAA_LVL_LOW_TIME">DAA_LVL_LOW_TIME</a></td><td>Expands the Well Clear base volume using aircraft speed and the configured time margin.</td></tr><tr><td>Velocity input</td><td><a href="./../advanced_config/parameter_reference#DAA_EN_DFLT_VEL">DAA_EN_DFLT_VEL</a>, <a href="./../advanced_config/parameter_reference#DAA_DFLT_VEL">DAA_DFLT_VEL</a></td><td>Optional replacement for the reported traffic vertical speed.</td></tr></tbody></table><p>Changing an action parameter does not re-evaluate buffered conflicts immediately. The new action is considered on a later change of the overall most-urgent conflict level, and automatic mode changes are only requested when that level increases.</p><p>These parameters use the same action scale: <code>0</code>: Disabled, <code>1</code>: Warn only, <code>2</code>: Return, <code>3</code>: Land, <code>4</code>: Hold, <code>5</code>: Terminate.</p><p>Most users can start with the default F3442 volume parameters and tune them only if needed. See <a href="./../advanced_features/detect_and_avoid#f3442-mode">Detect and Avoid &gt; F3442 Mode</a>, which also includes the zone-computation equations.</p><h3 id="arming-check-and-failsafe" tabindex="-1">Arming Check and Failsafe <a class="header-anchor" href="#arming-check-and-failsafe" aria-label="Permalink to &quot;Arming Check and Failsafe&quot;">​</a></h3><p>PX4 can be configured to warn about, or require, a traffic avoidance system (for example an ADS-B or FLARM receiver), and to trigger a failsafe if the system stops sending MAVLink heartbeats in flight.</p><p>This check only verifies that a traffic source is present. It is separate from DAA rejecting arming because active traffic already requires an automatic action; that behavior is described in <a href="./../advanced_features/detect_and_avoid#arming-preflight-and-ground-behavior">Detect and Avoid &gt; Arming, Preflight, and Ground Behavior</a>.</p><p>The behavior is configured using the <a href="./../advanced_config/parameter_reference#COM_TRAFF_AVOID">COM_TRAFF_AVOID</a> parameter:</p><table tabindex="0"><thead><tr><th>Value</th><th>설명</th></tr></thead><tbody><tr><td>0</td><td>Disabled (default). No check is performed.</td></tr><tr><td>1</td><td>Warning (allow arming). Arming is allowed even if no traffic avoidance system is detected; a warning is issued if it is missing or lost in flight.</td></tr><tr><td>2</td><td>Error (block arming). Arming is denied while no traffic avoidance system is detected, and a warning is issued if it is lost in flight.</td></tr><tr><td>3</td><td>Return. Arming is denied while no traffic avoidance system is detected, and the vehicle returns if it is lost in flight.</td></tr><tr><td>4</td><td>Land. Arming is denied while no traffic avoidance system is detected, and the vehicle lands if it is lost in flight.</td></tr></tbody></table><p>When a traffic avoidance system is detected, the system tracks its presence with a 3-second timeout. If the system is lost or regained, corresponding events are logged (&quot;Traffic avoidance system lost&quot; / &quot;Traffic avoidance system regained&quot;).</p><h2 id="시험" tabindex="-1">시험 <a class="header-anchor" href="#시험" aria-label="Permalink to &quot;시험&quot;">​</a></h2><p>To test your DAA configuration using simulated traffic, see <a href="./../advanced_features/detect_and_avoid#testing-and-simulation">Detect and Avoid &gt; Testing and Simulation</a>.</p><h2 id="추가-정보" tabindex="-1">추가 정보 <a class="header-anchor" href="#추가-정보" aria-label="Permalink to &quot;추가 정보&quot;">​</a></h2><ul><li><a href="./../advanced_features/detect_and_avoid">Detect and Avoid</a></li><li><a href="./../peripherals/mavlink_peripherals">MAVLink Peripherals</a></li><li><a href="./../peripherals/serial_configuration">Serial Port Configuration</a></li></ul>',56)])])}const p=t(i,[["render",o]]);export{_ as __pageData,p as default};
